    {
        foreach (NarrativeOption option in MainlandChildhoodOptions.Shared)
            yield return option;

        yield return new NarrativeOption("ironislander_childhood_finger_dance_option", new TextObject("{=bab_ironislander_childhood_finger_dance_title}played the finger dance."), new TextObject("{=bab_ironislander_childhood_finger_dance_desc}You joined older children in the dangerous game of tossing and catching a hand axe, learning quick feet, a steady eye, and little fear of blood."), (args, u) => u.UpgradeThrowingOneHandedSkills(args, DefaultCharacterAttributes.Control), ccm => IsIronIslander(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_fox"));
        yield return new NarrativeOption("ironislander_childhood_oars_option", new TextObject("{=bab_ironislander_childhood_oars_title}learned the oar and sail."), new TextObject("{=bab_ironislander_childhood_oars_desc}You spent your childhood in fishing boats and longships, hauling rope, pulling an oar, reading wind, and finding balance on a rolling deck."), (args, u) => u.UpgradeAthleticsCraftingSkills(args, DefaultCharacterAttributes.Endurance), ccm => IsIronIslander(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_athlete"));
        yield return new NarrativeOption("ironislander_childhood_reavers_tales_option", new TextObject("{=bab_ironislander_childhood_reavers_tales_title}listened to the tales of captains and reavers."), new TextObject("{=bab_ironislander_childhood_reavers_tales_desc}At the hearth you memorized boast, feud, voyage, and raid, learning which captains won loyalty and which brought their crews only grief."), (args, u) => u.UpgradeLeadershipTacticsSkills(args, DefaultCharacterAttributes.Social), ccm => IsIronIslander(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_memory"));
    }

    public IEnumerable<NarrativeOption> GetEducationOptions()
    {
        foreach (NarrativeOption option in MainlandEducationOptions.Shared)
            yield return option;

        yield return new NarrativeOption("ironislander_education_joined_crew_option", new TextObject("{=bab_ironislander_education_joined_crew_title}joined a longship's crew."), new TextObject("{=bab_ironislander_education_joined_crew_desc}At the age when other children entered apprenticeships, you went aboard a longship and learned the oar, sail, axe, and harsh discipline of a captain's crew."), (args, u) => u.UpgradeAthleticsOneHandedSkills(args, DefaultCharacterAttributes.Vigor), ccm => IsIronIslander(ccm) && ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer && !CharacterObject.PlayerCharacter.IsFemale, ccm => MainlandEducationOptions.SetEducationAnim(ccm, "act_childhood_athlete", "", ""));
        yield return new NarrativeOption("ironislander_education_captains_hall_option", new TextObject("{=bab_ironislander_education_captains_hall_title}helped govern a captain's hall."), new TextObject("{=bab_ironislander_education_captains_hall_desc}You learned to reckon stores, direct servants and thralls, receive petitioners, and keep a hard household functioning while its fighting men were away at sea."), (args, u) => u.UpgradeStewardTacticsSkills(args, DefaultCharacterAttributes.Intelligence), ccm => IsIronIslander(ccm) && ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer && CharacterObject.PlayerCharacter.IsFemale, ccm => MainlandEducationOptions.SetEducationAnim(ccm, "act_childhood_manners", "", ""));
        yield return new NarrativeOption("ironislander_education_shipwright_option", new TextObject("{=bab_ironislander_education_shipwright_title}worked beside shipwrights and sailmakers."), new TextObject("{=bab_ironislander_education_shipwright_desc}You carried timber, pitch, rope, and cloth while learning how island craftsmen built and supplied the longships upon which every captain's fortune depended."), (args, u) => u.UpgradeTradeCraftingSkills(args, DefaultCharacterAttributes.Intelligence), ccm => IsIronIslander(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.MerchantUrban || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.ArtisanUrban), ccm => MainlandEducationOptions.SetEducationAnim(ccm, "act_childhood_grit", "", ""));
        yield return new NarrativeOption("ironislander_education_nets_halls_option", new TextObject("{=bab_ironislander_education_nets_halls_title}tended nets and salt-stained halls."), new TextObject("{=bab_ironislander_education_nets_halls_desc}While the men were away at sea, you mended nets, smoked fish, counted stores, and helped keep a hard island household alive until the sails returned."), (args, u) => u.UpgradeLeadershipStewardSkills(args, DefaultCharacterAttributes.Endurance), ccm => IsIronIslander(ccm) && CharacterObject.PlayerCharacter.IsFemale && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Farmer || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Hunter || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer), ccm => MainlandEducationOptions.SetEducationAnim(ccm, "act_childhood_grit", "", ""));
