        yield return new NarrativeOption("ironislander_youth_captains_daughter_option", new TextObject("{=bab_ironislander_youth_captains_daughter_title}claimed a warrior's place among the crew."), new TextObject("{=bab_ironislander_youth_captains_daughter_desc}Some men mocked a woman who wanted axe and command. You answered with skill, nerve, and the loyalty of shipmates willing to follow you."), (args, u) => u.UpgradeLeadershipTacticsSkills(args, DefaultCharacterAttributes.Social), ccm => IsIronIslander(ccm) && (CharacterObject.PlayerCharacter.IsFemale && (NarrativeChoiceState.ChildhoodWas("ironislander_childhood_finger_dance_option", "ironislander_childhood_oars_option", "childhood_brawn_option") || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer)), ccm => SelectYouth(ccm, "cavalry", "act_childhood_fierce"));
        yield return new NarrativeOption("ironislander_youth_hall_keeper_option", new TextObject("{=bab_ironislander_youth_hall_keeper_title}managed a captain's hall and stores."), new TextObject("{=bab_ironislander_youth_hall_keeper_desc}You directed thralls and servants, accounted for food and plunder, heard petitions, and kept the household strong while ships were away."), (args, u) => u.UpgradeLeadershipStewardSkills(args, DefaultCharacterAttributes.Intelligence), ccm => IsIronIslander(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Retainer || NarrativeChoiceState.EducationWas("ironislander_education_captains_hall_option")), ccm => SelectYouth(ccm, "noble", "act_childhood_manners"));
        yield return new NarrativeOption("ironislander_youth_shipwright_option", new TextObject("{=bab_ironislander_youth_shipwright_title}apprenticed with shipwrights and sailmakers."), new TextObject("{=bab_ironislander_youth_shipwright_desc}You learned the timber, iron, rope, pitch, and cloth that turned island labour into a swift longship."), (args, u) => u.UpgradeTradeCraftingSkills(args, DefaultCharacterAttributes.Intelligence), ccm => IsIronIslander(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.ArtisanUrban || NarrativeChoiceState.EducationWas("ironislander_education_shipwright_option")), ccm => SelectYouth(ccm, "guard", "act_childhood_grit"));
