        yield return new NarrativeOption("ironislander_adulthood_hall_rule_option", new TextObject("{=bab_ironislander_adulthood_hall_rule_title}you kept a great hall together through a hard absence."), new TextObject("{=bab_ironislander_adulthood_hall_rule_desc}With the fighting men at sea, you rationed stores, settled quarrels, and kept dependants loyal until the ships returned."), (args, u) => { u.UpgradeLeadershipStewardSkills(args, DefaultCharacterAttributes.Social); args.SetRenownToAdd(15); }, ccm => IsIronIslander(ccm) && (NarrativeChoiceState.YouthWas("ironislander_youth_hall_keeper_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_manners"));
