        yield return new NarrativeOption("ironislander_adulthood_salt_fish_option", new TextObject("{=bab_ironislander_adulthood_salt_fish_title}you captained a fishing longship and worked the shore trade."), new TextObject("{=bab_ironislander_adulthood_salt_fish_desc}You organized boats and nets at sea, then smokehouses, curing sheds, and salt pans ashore, helping feed the isles while the reaving ships were away."), (args, u) => { u.UpgradeTradeLeadershipSkills(args, DefaultCharacterAttributes.Intelligence); args.SetRenownToAdd(5); }, ccm => IsIronIslander(ccm) && (ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Farmer || ccm.CharacterCreationContent.SelectedParentOccupation == CharacterOccupations.Hunter || NarrativeChoiceState.EducationWas("ironislander_education_nets_halls_option") || NarrativeChoiceState.YouthWas("westerosi_youth_family_farm_option", "ironislander_youth_navigator_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_grit"));
